// Namespaces to process
const NAMESPACES = ['common', 'navigation', 'home', 'pages', 'forms'];

function mergeWithEnglish(langData, enData) {
  const result = {};
  for (const ns of NAMESPACES) {
    result[ns] = { ...(enData[ns] || {}), ...(langData[ns] || {}) };
  }
  return result;
}

let totalFiles = 0;

// Write fully translated locales (en, tr, fr, ja, ar)
for (const [locale, data] of Object.entries(translations)) {
  mkdirSync(join(LOCALES_DIR, locale), { recursive: true });
  for (const ns of NAMESPACES) {
    if (data[ns]) {
      const filePath = join(LOCALES_DIR, locale, `${ns}.json`);
      writeFileSync(filePath, JSON.stringify(data[ns], null, 2) + '\n');
      totalFiles++;
    }
  }
}

// Write derived locales (merge with English as base)
for (const [locale, langOverrides] of Object.entries(derivedFromEnglish)) {
  mkdirSync(join(LOCALES_DIR, locale), { recursive: true });
  const merged = mergeWithEnglish(langOverrides, translations.en);
  for (const ns of NAMESPACES) {
    if (merged[ns]) {
      const filePath = join(LOCALES_DIR, locale, `${ns}.json`);
      writeFileSync(filePath, JSON.stringify(merged[ns], null, 2) + '\n');
      totalFiles++;
    }
  }
}

console.log(`✅ Generated ${totalFiles} expanded JSON files for ${Object.keys(translations).length + Object.keys(derivedFromEnglish).length} locales`);

// Copy to public/locales
import { execSync } from 'child_process';
execSync('rm -rf public/locales && cp -r locales public/locales');
console.log('✅ Synced to public/locales/');
